parameters.jsCode:
/**
 * Shared front-of-funnel logic.
 *
 * This file is the single source of truth for lead parsing, reference tokens,
 * Tier A guardrails, and the pre-qualification gate. The build scripts inline it
 * into n8n Code nodes, so it must stay dependency-free and must not use
 * backticks or template literals - those are consumed before reaching the node.
 *
 * Nothing here calls a model. Everything here is deterministic.
 */

/* ------------------------------------------------------------------ tokens */

/**
 * Reference token carried in every subject line. Replies are matched on this
 * first and on sender address only as a fallback - the model never decides
 * which lead a message belongs to.
 */
function makeRefToken(prefix, seed) {
  var n = seed === undefined ? Math.floor(Math.random() * 9000) + 1000 : seed;
  return prefix + "-" + String(n).slice(0, 4);
}

function extractRefToken(text) {
  if (!text) return null;
  var match = String(text).match(/\[([RA]-\d{4})\]/);
  return match ? match[1] : null;
}

function subjectWithToken(subject, token) {
  if (extractRefToken(subject)) return subject;
  return subject + " [" + token + "]";
}

/* ------------------------------------------------------- lead email parsing */

/**
 * Parses a listing-site lead notification.
 *
 * Zillow delivers these as email with an anonymised relay reply-to and no phone
 * number, so the parser must tolerate a missing phone rather than treat it as a
 * failure. Anything it cannot determine is left null and flagged, never guessed.
 */
function parseLeadEmail(input) {
  var subject = input.subject || "";
  var body = input.body || "";
  var replyTo = input.replyTo || input.from || "";

  var result = {
    prospect_name: null,
    prospect_email: null,
    prospect_phone: null,
    unit_hint: null,
    inquiry_text: null,
    source: "zillow_email",
    parse_warnings: [],
  };

  var nameMatch = body.match(/^\s*Renter:\s*(.+)$/m);
  if (nameMatch) result.prospect_name = nameMatch[1].trim();
  else result.parse_warnings.push("no renter name found");

  var propertyMatch = body.match(/^\s*Property:\s*(.+)$/m);
  if (propertyMatch) result.unit_hint = propertyMatch[1].trim();
  else {
    var subjectUnit = subject.match(/:\s*(.+)$/);
    if (subjectUnit) result.unit_hint = subjectUnit[1].trim();
    else result.parse_warnings.push("no property reference found");
  }

  // The renter's own words, between the quotes after "Message:".
  var messageMatch = body.match(/Message:\s*"([\s\S]*?)"/);
  if (messageMatch) result.inquiry_text = messageMatch[1].replace(/\s+/g, " ").trim();
  else result.parse_warnings.push("no inquiry text found");

  var emailMatch = String(replyTo).match(/[\w.+-]+@[\w.-]+\.\w+/);
  if (emailMatch) result.prospect_email = emailMatch[0];
  else result.parse_warnings.push("no reply address found");

  var phoneMatch = body.match(/(\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/);
  if (phoneMatch) result.prospect_phone = phoneMatch[0].trim();

  return result;
}

/* ------------------------------------------------- unit knowledge for the AI */

/**
 * Flattens a unit row into the only facts the FAQ model is allowed to use.
 * If a fact is not in here, the correct answer is "I don't have that".
 */
function buildUnitKnowledge(unit) {
  if (!unit) return null;
  var facts = unit.faq_facts || {};
  var knowledge = {
    unit_code: unit.unit_code,
    address: unit.address,
    bedrooms: unit.beds,
    bathrooms: Number(unit.baths),
    square_feet: unit.sqft,
    monthly_rent: Number(unit.rent_amount),
    security_deposit: Number(unit.deposit_amount),
    available_from: unit.available_from,
    lease_term_months: unit.lease_term_months,
    pet_policy: unit.pet_policy,
    pet_fee_monthly: unit.pet_fee_monthly === null ? null : Number(unit.pet_fee_monthly),
    parking: unit.parking,
    utilities: unit.utilities_included,
    laundry: unit.laundry,
  };
  Object.keys(facts).forEach(function (key) {
    knowledge[key] = facts[key];
  });
  return knowledge;
}

/**
 * Unit facts PLUS the figures the prospect themselves stated, for use as the
 * guardrail's allowlist during a conversation.
 *
 * The unsupported-figure rule exists to stop the model inventing a rent, a fee
 * or a deposit. It is not meant to stop it repeating a number the prospect just
 * supplied - and in a chat, confirming what someone told you ("$5,000 a month,
 * got it") is the natural thing to say. With only unit facts in the allowlist
 * every such reply is blocked, the prospect gets silence, and the conversation
 * stalls on the most ordinary turn there is.
 *
 * Only the recorded slot values are added, never arbitrary numbers scraped from
 * the message, so the check still catches anything the model made up.
 */
function buildConversationKnowledge(unit, statedAnswers) {
  var knowledge = buildUnitKnowledge(unit);
  if (!knowledge) return null;
  var answers = statedAnswers || {};

  if (answers.stated_monthly_income !== null && answers.stated_monthly_income !== undefined) {
    knowledge.prospect_stated_monthly_income = Number(answers.stated_monthly_income);
  }
  if (answers.vehicles !== null && answers.vehicles !== undefined) {
    knowledge.prospect_stated_vehicles = Number(answers.vehicles);
  }
  if (answers.occupants !== null && answers.occupants !== undefined) {
    knowledge.prospect_stated_occupants = Number(answers.occupants);
  }
  if (answers.pets !== null && answers.pets !== undefined && answers.pets !== "") {
    knowledge.prospect_stated_pets = String(answers.pets);
  }
  if (answers.move_in_date !== null && answers.move_in_date !== undefined) {
    knowledge.prospect_stated_move_in = String(answers.move_in_date);
  }
  return knowledge;
}

/**
 * Escapes text for Telegram's HTML parse mode.
 *
 * The Telegram node always sends a parse_mode, so message text is parsed for
 * entities whether you want it or not. Under the legacy Markdown default a
 * single underscore opens an italic run that never closes, and Telegram rejects
 * the whole message with "can't parse entities" and a byte offset - which is
 * exactly what an application link carrying ?ref_token= does. The node then
 * fails with a bare "Bad request - please check your parameters".
 *
 * So: send HTML parse mode and escape the three characters it cares about.
 * Underscores, asterisks and brackets are then all literal, and a URL with a
 * query string is safe.
 */
function escapeTelegramHtml(text) {
  if (text === null || text === undefined) return "";
  return String(text)
    .split("&").join("&amp;")
    .split("<").join("&lt;")
    .split(">").join("&gt;");
}

/* ------------------------------------------------------------------- tours */

/**
 * Turns a naive datetime into a real instant, read as PROPERTY-LOCAL time.
 *
 * The model returns "2026-09-15T14:00" when someone says "Tuesday at 2pm", and
 * they mean 2pm at the property. `new Date()` on a bare string with no zone
 * reads it in the runtime's zone - UTC in a container - so a request for 2pm
 * silently became 9:30am and the renter was booked five hours out. Nothing
 * errors; you only notice by reading the booked time.
 *
 * Anything already carrying a Z or a +/-HH:MM offset is left exactly alone.
 */
function naiveLocalToUtcIso(naive, timeZone) {
  if (!naive) return null;
  var text = String(naive).trim();
  if (/(Z|[+-]\d{2}:?\d{2})$/.test(text)) return new Date(text).toISOString();

  var guess = new Date(text + "Z");
  if (isNaN(guess.getTime())) return null;

  // How far ahead of UTC that zone is at that instant, DST included.
  var dtf = new Intl.DateTimeFormat("en-US", {
    timeZone: timeZone || "UTC", hour12: false,
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit",
  });
  var parts = {};
  dtf.formatToParts(guess).forEach(function (p) { parts[p.type] = p.value; });
  var asUtc = Date.UTC(
    Number(parts.year), Number(parts.month) - 1, Number(parts.day),
    Number(parts.hour) % 24, Number(parts.minute), Number(parts.second)
  );
  var offset = asUtc - guess.getTime();
  return new Date(guess.getTime() - offset).toISOString();
}

/**
 * Picks the real Cal.com slot closest to what the prospect asked for.
 *
 * The model turns "Saturday morning" into an ISO datetime; it never chooses the
 * booking. This does, deterministically, against the slots Cal.com actually
 * returned - so the assistant can only ever book a time that genuinely exists.
 *
 * `slots` is a flat array of ISO strings. Returns the nearest slot within
 * `toleranceHours`, plus the next few alternatives to offer if nothing is close.
 */
function matchTourSlot(wantedIso, slots, toleranceHours) {
  var tolerance = (toleranceHours === undefined ? 4 : toleranceHours) * 3600000;
  var available = (slots || []).slice().sort();
  var result = { matched: null, delta_minutes: null, alternatives: available.slice(0, 3) };
  if (!wantedIso || !available.length) return result;

  var wanted = new Date(wantedIso).getTime();
  if (isNaN(wanted)) return result;

  var best = null;
  var bestDelta = Infinity;
  for (var i = 0; i < available.length; i++) {
    var delta = Math.abs(new Date(available[i]).getTime() - wanted);
    if (delta < bestDelta) { bestDelta = delta; best = available[i]; }
  }

  // Alternatives are the slots nearest what they asked for, not simply the
  // earliest ones - "how about Tuesday?" should not be answered with Monday 9am.
  result.alternatives = available
    .slice()
    .sort(function (a, b) {
      return Math.abs(new Date(a).getTime() - wanted) - Math.abs(new Date(b).getTime() - wanted);
    })
    .slice(0, 3)
    .sort();

  if (best !== null && bestDelta <= tolerance) {
    result.matched = best;
    result.delta_minutes = Math.round(bestDelta / 60000);
  }
  return result;
}

/**
 * Is this slot inside the manager's published tour policy, or an exception?
 *
 * Exceptions are held for a tap rather than refused. Returning reasons rather
 * than a bare boolean means the manager's card can say WHY it was held, which
 * is the difference between a useful notification and an interruption.
 *
 * `hourOverride` exists because a Code node cannot rely on the container's
 * timezone; the caller passes the local hour and weekday it computed.
 */
function classifyTourRequest(slotIso, policy, nowIso, hourOverride, weekdayOverride) {
  var reasons = [];
  var config = policy || {};
  var earliest = Number(config.earliest_hour === undefined ? 9 : config.earliest_hour);
  var latest = Number(config.latest_hour === undefined ? 18 : config.latest_hour);
  var minNotice = Number(config.min_notice_hours === undefined ? 12 : config.min_notice_hours);
  var allowWeekends = config.allow_weekends === undefined ? true : Boolean(config.allow_weekends);

  var slot = new Date(slotIso);
  var now = new Date(nowIso || new Date().toISOString());
  var hour = hourOverride === undefined || hourOverride === null ? slot.getUTCHours() : Number(hourOverride);
  var weekday = weekdayOverride === undefined || weekdayOverride === null
    ? slot.getUTCDay()
    : Number(weekdayOverride);

  if (hour < earliest || hour >= latest) {
    reasons.push("outside self-guided hours (" + earliest + ":00-" + latest + ":00)");
  }
  if (!allowWeekends && (weekday === 0 || weekday === 6)) {
    reasons.push("weekend");
  }
  var noticeHours = (slot.getTime() - now.getTime()) / 3600000;
  if (noticeHours < minNotice) {
    reasons.push("less than " + minNotice + "h notice (" + Math.max(0, Math.round(noticeHours)) + "h)");
  }

  return {
    is_exception: reasons.length > 0,
    reasons: reasons,
    notice_hours: Math.round(noticeHours),
  };
}

/* -------------------------------------------------------------- guardrails */

/**
 * Tier A guardrail. Runs on every message before it leaves, and again at send
 * time, because a manager may have edited the wording after it was drafted.
 *
 * Blocks: protected-class content, legal or lease commitments, rent negotiation,
 * availability promises, and invented numbers that are not in the unit facts.
 */
var PROTECTED_CLASS_PATTERNS = [
  { pattern: /\b(kids?|children|child|family friendly|families|school district)\b/i, label: "familial status" },
  { pattern: /\b(disab|wheelchair|handicap|mental health|service animal policy)\b/i, label: "disability" },
  { pattern: /\b(race|ethnic|nationality|immigration|citizen|visa status)\b/i, label: "national origin / race" },
  { pattern: /\b(church|mosque|temple|synagogue|religio)\b/i, label: "religion" },
  { pattern: /\b(marital status|married|single people|couples only)\b/i, label: "marital status" },
  { pattern: /\b(section 8|voucher|housing assistance|welfare)\b/i, label: "source of income" },
  { pattern: /\b(good neighborhood for|safe area for|type of people)\b/i, label: "steering" },
];

var COMMITMENT_PATTERNS = [
  { pattern: /\b(guarantee|guaranteed|we promise|you will be approved|pre-?approved)\b/i, label: "approval commitment" },
  { pattern: /\b(hold (it|the unit) for you|reserved for you|it'?s yours)\b/i, label: "availability commitment" },
  { pattern: /\b(we can lower|discount the rent|negotiate the rent|reduce the rent)\b/i, label: "rent negotiation" },
  { pattern: /\b(legally|by law|you are entitled|your rights under)\b/i, label: "legal statement" },
  { pattern: /\b(denied|rejected|you do not qualify|we cannot rent to you)\b/i, label: "adverse decision language" },
];

function guardrailCheck(text, knowledge) {
  var findings = [];
  var body = String(text || "");

  PROTECTED_CLASS_PATTERNS.forEach(function (rule) {
    if (rule.pattern.test(body)) {
      findings.push({ severity: "block", category: "protected_class", detail: rule.label });
    }
  });

  COMMITMENT_PATTERNS.forEach(function (rule) {
    if (rule.pattern.test(body)) {
      findings.push({ severity: "block", category: "commitment", detail: rule.label });
    }
  });

  // Any dollar figure in the message must appear in the unit facts. Catches the
  // model inventing a rent, fee, or deposit.
  if (knowledge) {
    var allowed = [];
    Object.keys(knowledge).forEach(function (key) {
      var value = knowledge[key];
      if (typeof value === "number") allowed.push(Math.round(value));
      if (typeof value === "string") {
        var found = value.match(/\d[\d,]*(\.\d+)?/g) || [];
        found.forEach(function (n) { allowed.push(Math.round(Number(n.replace(/,/g, "")))); });
      }
    });

    var quoted = body.match(/\$\s?\d[\d,]*(\.\d+)?/g) || [];
    quoted.forEach(function (raw) {
      var amount = Math.round(Number(raw.replace(/[$,\s]/g, "")));
      if (allowed.indexOf(amount) === -1) {
        findings.push({
          severity: "block",
          category: "unsupported_figure",
          detail: raw.trim() + " is not in the unit facts",
        });
      }
    });
  }

  var blocking = findings.filter(function (f) { return f.severity === "block"; });
  return {
    passed: blocking.length === 0,
    findings: findings,
    checked_at: new Date().toISOString(),
  };
}

/* ------------------------------------------------------- pre-qualification */

/**
 * Scheduling triage only. This is NOT a rental decision and its output must
 * never be phrased to a prospect as a denial.
 *
 * Deliberately narrow: move-in timing, self-reported income against the
 * published multiple, pet policy, and occupancy. Nothing else is considered and
 * nothing here is verified.
 */
function prequalGate(answers, unit, config) {
  var reasons = [];
  var missing = [];
  var incomeMultiple = config && config.income_multiple ? Number(config.income_multiple) : 3;

  if (!answers || answers.move_in_date === null || answers.move_in_date === undefined) {
    missing.push("move_in_date");
  } else {
    var availableFrom = new Date(unit.available_from);
    var wanted = new Date(answers.move_in_date);
    var daysAfter = (wanted - availableFrom) / 86400000;

    if (daysAfter < -14) {
      reasons.push({
        criterion: "move_in_timing",
        met: false,
        detail: "wants " + answers.move_in_date + ", unit is available from " + unit.available_from,
      });
    } else if (daysAfter > 60) {
      reasons.push({
        criterion: "move_in_timing",
        met: false,
        detail: "move-in is more than 60 days after the unit is available",
      });
    } else {
      reasons.push({ criterion: "move_in_timing", met: true, detail: answers.move_in_date });
    }
  }

  if (answers && (answers.stated_monthly_income === null || answers.stated_monthly_income === undefined)) {
    missing.push("stated_monthly_income");
  } else if (answers) {
    // Self-reported and unverified. Verification happens after an application.
    var rent = Number(unit.rent_amount);
    var stated = Number(answers.stated_monthly_income);
    var ratio = stated / rent;
    reasons.push({
      criterion: "stated_income",
      met: ratio >= incomeMultiple,
      detail: "$" + stated + "/mo stated against $" + rent + " rent = " + ratio.toFixed(2) + "x (unverified)",
    });
  }

  if (answers && answers.pets && String(answers.pets).toLowerCase() !== "none") {
    var weightMatch = String(answers.pets).match(/(\d+)\s?(lb|pound)/i);
    var overLimit = weightMatch && Number(weightMatch[1]) > 50;
    reasons.push({
      criterion: "pets",
      met: !overLimit,
      detail: overLimit ? "stated pet is over the 50 lb limit" : String(answers.pets),
    });
  }

  var failed = reasons.filter(function (r) { return r.met === false; });
  var result = missing.length ? "incomplete" : failed.length ? "not_clear" : "clear";

  return {
    result: result,
    reasons: reasons,
    missing: missing,
    evaluated_at: new Date().toISOString(),
  };
}

/* ------------------------------------------------------- AI output shape */

/**
 * Unwraps structured output from the OpenAI node.
 *
 * The payload arrives wrapped differently depending on node version, whether
 * simplify is on, and whether a JSON schema was applied - sometimes a parsed
 * object, sometimes a JSON string under `output`, sometimes nested one level
 * deeper. Probing for a known key is more robust than assuming a shape.
 *
 * @param {*} data       the item's json
 * @param {string} anchor a key that must exist on the real payload
 */
function unwrapAiPayload(data, anchor) {
  var value = data;

  for (var depth = 0; depth < 6; depth++) {
    if (value === null || value === undefined) break;

    if (typeof value === "string") {
      var trimmed = value.trim();
      if (trimmed.charAt(0) !== "{" && trimmed.charAt(0) !== "[") break;
      try {
        value = JSON.parse(trimmed);
      } catch (error) {
        break;
      }
      continue;
    }

    if (Array.isArray(value)) {
      value = value[0];
      continue;
    }

    if (typeof value === "object") {
      if (Object.prototype.hasOwnProperty.call(value, anchor)) return value;

      var next =
        value.output !== undefined ? value.output :
        value.message !== undefined ? value.message :
        value.content !== undefined ? value.content :
        value.text !== undefined ? value.text :
        value.json !== undefined ? value.json : undefined;

      if (next === undefined) break;
      value = next;
      continue;
    }

    break;
  }

  return value;
}

/* ------------------------------------------------------------- lock code */

/**
 * Self-guided tour entry code.
 *
 * MOCK. A real deployment issues this through a smart-lock platform
 * (Rently, Tour24, ButterflyMX) bound to the booking window. Here it is
 * generated locally and logged, and every record it touches is marked
 * source: "mock".
 */
function generateLockCode() {
  var code = String(Math.floor(Math.random() * 900000) + 100000);
  return { code: code, source: "mock", issued_at: new Date().toISOString() };
}

var COLLECT_ORDER = ['move_in_date', 'stated_monthly_income', 'pets', 'vehicles', 'occupants'];

var QUESTION_PROMPTS = {
  move_in_date: 'When are you hoping to move in?',
  stated_monthly_income: 'Roughly what is your gross monthly income? This is just to check which units fit, not a decision.',
  pets: 'Do you have any pets? If so, what kind and roughly what weight?',
  vehicles: 'How many vehicles would need parking?',
  occupants: 'How many adults would be living there?',
};

var TOUR_PROMPT = 'Everything looks like a fit so far. Here is the link to pick a tour time that suits you:';
var ALTERNATIVES_PROMPT = 'Thanks for those details. Based on what you have told us this one may not be the closest match on timing or size, but we would still like to help - a member of the team will follow up with other options. If you would like to tour this unit anyway, just say so and we will set it up.';
var HANDOFF_PROMPT = 'Let me get a member of the team to pick this up with you. They will be in touch shortly.';
var MAX_TELEGRAM = 4000;

// The deterministic half of a conversation turn.
//
// The model produced an answer and an extraction. Everything that decides
// what happens next - which slot to ask for, whether a tour is offered, what
// wording is used - happens here, in plain JavaScript, over the manager's
// configured criteria.
const context = $('Build Conversation Context').first().json;
const lead = $('Bind Lead Identity').first().json;
const config = $('Load Active Criteria').first().json;
const inbound = $('Normalize Telegram Message').first().json;

const payload = unwrapAiPayload($input.first().json, 'reply_text');
const replyText = payload && typeof payload === 'object' ? String(payload.reply_text || '') : '';

// One call now carries both the answer and the extraction, so a malformed
// payload could blank the reply AND wipe the slots. Throw before anything is
// merged rather than sending an empty message and recording empty answers.
if (!replyText.trim() || !payload.prequal || typeof payload.prequal !== 'object') {
  throw new Error(
    'Conversation turn returned an unexpected shape. Raw keys: ' +
    JSON.stringify(Object.keys($input.first().json || {})) +
    ' unwrapped: ' + JSON.stringify(payload).slice(0, 400)
  );
}

// Merge: a slot the prospect did not restate keeps the value already on
// record. A null never overwrites a stated answer.
const known = context.known_slots || {};
const answers = {};
for (const key of COLLECT_ORDER) {
  const fresh = payload.prequal[key];
  answers[key] = fresh === null || fresh === undefined || fresh === '' ? known[key] : fresh;
  if (answers[key] === undefined) answers[key] = null;
}
if (answers.stated_monthly_income !== null) {
  answers.stated_monthly_income = Number(answers.stated_monthly_income);
}

const outcome = prequalGate(answers, context.unit, config);

const state = lead.conversation_state || {};
const asked = Array.isArray(state.asked) ? state.asked.slice() : [];
const wantsHuman = Boolean(payload.wants_human) || context.force_handoff;

// What is still outstanding, in ask order, skipping anything already asked.
const outstanding = COLLECT_ORDER.filter(function (key) {
  return answers[key] === null || answers[key] === undefined || answers[key] === '';
});
const unasked = outstanding.filter(function (key) { return asked.indexOf(key) === -1; });

let stage;
let nextAsk = null;
let appended;

if (wantsHuman) {
  stage = 'handoff';
  appended = HANDOFF_PROMPT;
} else if (outcome.result === 'not_clear') {
  // Never a refusal. Pre-qualification is scheduling triage on unverified
  // answers and is never phrased to the prospect as a decision.
  stage = 'not_clear';
  appended = ALTERNATIVES_PROMPT;
} else if (unasked.length) {
  stage = 'collecting';
  nextAsk = unasked[0];
  appended = QUESTION_PROMPTS[nextAsk];
} else if (outcome.result === 'clear') {
  stage = 'clear';
  appended = TOUR_PROMPT + '\n__CALCOM_BOOKING_URL__?metadata[ref_token]=' + lead.ref_token;
} else if (outstanding.length) {
  // Everything has been asked once and something is still missing. Ask the
  // most important one again rather than looping silently.
  stage = 'reasking';
  nextAsk = outstanding[0];
  appended = QUESTION_PROMPTS[nextAsk];
} else {
  stage = 'handoff';
  appended = HANDOFF_PROMPT;
}

let finalText = replyText.trim() + '\n\n' + appended;
if (finalText.length > MAX_TELEGRAM) finalText = finalText.slice(0, MAX_TELEGRAM);

if (nextAsk && asked.indexOf(nextAsk) === -1) asked.push(nextAsk);

const nextState = {
  inquiry_text: state.inquiry_text || null,
  asked: asked,
  last_intent: payload.intent || null,
  reask_count: stage === 'reasking' ? Number(state.reask_count || 0) + 1 : Number(state.reask_count || 0),
  turn_count: context.turn_count,
  wants_human: wantsHuman,
};

// Mirror at PHASE BOUNDARIES ONLY. Airtable Free allows 1000 API calls a
// month per workspace, and a chat is many turns - mirroring every turn would
// burn the quota and stack duplicate-looking writes on the board. This mirrors
// the same status transition the UPDATE below applies, so the two cannot
// disagree about what phase the lead is in.
let nextStatus = lead.status;
if (outcome.result === 'clear' && (lead.status === 'new' || lead.status === 'engaged')) {
  nextStatus = 'prequalified';
} else if (lead.status === 'new') {
  nextStatus = 'engaged';
}
const phaseChanged = nextStatus !== lead.status;

const STATUS_LABELS = {
  new: 'New',
  engaged: 'Engaged',
  prequalified: 'Prequalified',
  tour_booked: 'Tour Booked',
  toured: 'Toured',
  applied: 'Applied',
};

return [{
  json: {
    ref_token: lead.ref_token,
    telegram_chat_id: lead.telegram_chat_id || inbound.chat_id,
    prospect_name: lead.prospect_name,
    prospect_email: lead.prospect_email,
    unit_code: context.unit.unit_code,
    address: context.unit.address,
    answers: answers,
    prequal_result: outcome.result,
    prequal_reasons: outcome.reasons,
    prequal_missing: outcome.missing,
    stage: stage,
    next_ask: nextAsk,
    intent: payload.intent || null,
    tour_preference: payload.tour_preference || null,
    // Only chase a booking once the gate is happy and nothing is outstanding.
    wants_tour_slot: Boolean(payload.tour_preference) && outcome.result === 'clear' &&
      !unasked.length && lead.status !== 'tour_booked' && lead.tour_approval_state !== 'pending',
    wants_human: wantsHuman,
    questions_answered: payload.questions_answered || [],
    questions_unanswered: payload.questions_unanswered || [],
    refused_questions: payload.refused_questions || [],
    reply_text: finalText,
    conversation_state: nextState,
    needs_manager: stage === 'not_clear' || wantsHuman,
    phase_changed: phaseChanged,
    next_status: nextStatus,
    next_status_label: STATUS_LABELS[nextStatus] || 'Engaged',
  },
}];

/**
 * Shared front-of-funnel logic.
 *
 * This file is the single source of truth for lead parsing, reference tokens,
 * Tier A guardrails, and the pre-qualification gate. The build scripts inline it
 * into n8n Code nodes, so it must stay dependency-free and must not use
 * backticks or template literals - those are consumed before reaching the node.
 *
 * Nothing here calls a model. Everything here is deterministic.
 */

/* ------------------------------------------------------------------ tokens */

/**
 * Reference token carried in every subject line. Replies are matched on this
 * first and on sender address only as a fallback - the model never decides
 * which lead a message belongs to.
 */
function makeRefToken(prefix, seed) {
  var n = seed === undefined ? Math.floor(Math.random() * 9000) + 1000 : seed;
  return prefix + "-" + String(n).slice(0, 4);
}

function extractRefToken(text) {
  if (!text) return null;
  var match = String(text).match(/\[([RA]-\d{4})\]/);
  return match ? match[1] : null;
}

function subjectWithToken(subject, token) {
  if (extractRefToken(subject)) return subject;
  return subject + " [" + token + "]";
}

/* ------------------------------------------------------- lead email parsing */

/**
 * Parses a listing-site lead notification.
 *
 * Zillow delivers these as email with an anonymised relay reply-to and no phone
 * number, so the parser must tolerate a missing phone rather than treat it as a
 * failure. Anything it cannot determine is left null and flagged, never guessed.
 */
function parseLeadEmail(input) {
  var subject = input.subject || "";
  var body = input.body || "";
  var replyTo = input.replyTo || input.from || "";

  var result = {
    prospect_name: null,
    prospect_email: null,
    prospect_phone: null,
    unit_hint: null,
    inquiry_text: null,
    source: "zillow_email",
    parse_warnings: [],
  };

  var nameMatch = body.match(/^\s*Renter:\s*(.+)$/m);
  if (nameMatch) result.prospect_name = nameMatch[1].trim();
  else result.parse_warnings.push("no renter name found");

  var propertyMatch = body.match(/^\s*Property:\s*(.+)$/m);
  if (propertyMatch) result.unit_hint = propertyMatch[1].trim();
  else {
    var subjectUnit = subject.match(/:\s*(.+)$/);
    if (subjectUnit) result.unit_hint = subjectUnit[1].trim();
    else result.parse_warnings.push("no property reference found");
  }

  // The renter's own words, between the quotes after "Message:".
  var messageMatch = body.match(/Message:\s*"([\s\S]*?)"/);
  if (messageMatch) result.inquiry_text = messageMatch[1].replace(/\s+/g, " ").trim();
  else result.parse_warnings.push("no inquiry text found");

  var emailMatch = String(replyTo).match(/[\w.+-]+@[\w.-]+\.\w+/);
  if (emailMatch) result.prospect_email = emailMatch[0];
  else result.parse_warnings.push("no reply address found");

  var phoneMatch = body.match(/(\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/);
  if (phoneMatch) result.prospect_phone = phoneMatch[0].trim();

  return result;
}

/* ------------------------------------------------- unit knowledge for the AI */

/**
 * Flattens a unit row into the only facts the FAQ model is allowed to use.
 * If a fact is not in here, the correct answer is "I don't have that".
 */
function buildUnitKnowledge(unit) {
  if (!unit) return null;
  var facts = unit.faq_facts || {};
  var knowledge = {
    unit_code: unit.unit_code,
    address: unit.address,
    bedrooms: unit.beds,
    bathrooms: Number(unit.baths),
    square_feet: unit.sqft,
    monthly_rent: Number(unit.rent_amount),
    security_deposit: Number(unit.deposit_amount),
    available_from: unit.available_from,
    lease_term_months: unit.lease_term_months,
    pet_policy: unit.pet_policy,
    pet_fee_monthly: unit.pet_fee_monthly === null ? null : Number(unit.pet_fee_monthly),
    parking: unit.parking,
    utilities: unit.utilities_included,
    laundry: unit.laundry,
  };
  Object.keys(facts).forEach(function (key) {
    knowledge[key] = facts[key];
  });
  return knowledge;
}

/**
 * Unit facts PLUS the figures the prospect themselves stated, for use as the
 * guardrail's allowlist during a conversation.
 *
 * The unsupported-figure rule exists to stop the model inventing a rent, a fee
 * or a deposit. It is not meant to stop it repeating a number the prospect just
 * supplied - and in a chat, confirming what someone told you ("$5,000 a month,
 * got it") is the natural thing to say. With only unit facts in the allowlist
 * every such reply is blocked, the prospect gets silence, and the conversation
 * stalls on the most ordinary turn there is.
 *
 * Only the recorded slot values are added, never arbitrary numbers scraped from
 * the message, so the check still catches anything the model made up.
 */
function buildConversationKnowledge(unit, statedAnswers) {
  var knowledge = buildUnitKnowledge(unit);
  if (!knowledge) return null;
  var answers = statedAnswers || {};

  if (answers.stated_monthly_income !== null && answers.stated_monthly_income !== undefined) {
    knowledge.prospect_stated_monthly_income = Number(answers.stated_monthly_income);
  }
  if (answers.vehicles !== null && answers.vehicles !== undefined) {
    knowledge.prospect_stated_vehicles = Number(answers.vehicles);
  }
  if (answers.occupants !== null && answers.occupants !== undefined) {
    knowledge.prospect_stated_occupants = Number(answers.occupants);
  }
  if (answers.pets !== null && answers.pets !== undefined && answers.pets !== "") {
    knowledge.prospect_stated_pets = String(answers.pets);
  }
  if (answers.move_in_date !== null && answers.move_in_date !== undefined) {
    knowledge.prospect_stated_move_in = String(answers.move_in_date);
  }
  return knowledge;
}

/**
 * Escapes text for Telegram's HTML parse mode.
 *
 * The Telegram node always sends a parse_mode, so message text is parsed for
 * entities whether you want it or not. Under the legacy Markdown default a
 * single underscore opens an italic run that never closes, and Telegram rejects
 * the whole message with "can't parse entities" and a byte offset - which is
 * exactly what an application link carrying ?ref_token= does. The node then
 * fails with a bare "Bad request - please check your parameters".
 *
 * So: send HTML parse mode and escape the three characters it cares about.
 * Underscores, asterisks and brackets are then all literal, and a URL with a
 * query string is safe.
 */
function escapeTelegramHtml(text) {
  if (text === null || text === undefined) return "";
  return String(text)
    .split("&").join("&amp;")
    .split("<").join("&lt;")
    .split(">").join("&gt;");
}

/* ------------------------------------------------------------------- tours */

/**
 * Turns a naive datetime into a real instant, read as PROPERTY-LOCAL time.
 *
 * The model returns "2026-09-15T14:00" when someone says "Tuesday at 2pm", and
 * they mean 2pm at the property. `new Date()` on a bare string with no zone
 * reads it in the runtime's zone - UTC in a container - so a request for 2pm
 * silently became 9:30am and the renter was booked five hours out. Nothing
 * errors; you only notice by reading the booked time.
 *
 * Anything already carrying a Z or a +/-HH:MM offset is left exactly alone.
 */
function naiveLocalToUtcIso(naive, timeZone) {
  if (!naive) return null;
  var text = String(naive).trim();
  if (/(Z|[+-]\d{2}:?\d{2})$/.test(text)) return new Date(text).toISOString();

  var guess = new Date(text + "Z");
  if (isNaN(guess.getTime())) return null;

  // How far ahead of UTC that zone is at that instant, DST included.
  var dtf = new Intl.DateTimeFormat("en-US", {
    timeZone: timeZone || "UTC", hour12: false,
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit",
  });
  var parts = {};
  dtf.formatToParts(guess).forEach(function (p) { parts[p.type] = p.value; });
  var asUtc = Date.UTC(
    Number(parts.year), Number(parts.month) - 1, Number(parts.day),
    Number(parts.hour) % 24, Number(parts.minute), Number(parts.second)
  );
  var offset = asUtc - guess.getTime();
  return new Date(guess.getTime() - offset).toISOString();
}

/**
 * Picks the real Cal.com slot closest to what the prospect asked for.
 *
 * The model turns "Saturday morning" into an ISO datetime; it never chooses the
 * booking. This does, deterministically, against the slots Cal.com actually
 * returned - so the assistant can only ever book a time that genuinely exists.
 *
 * `slots` is a flat array of ISO strings. Returns the nearest slot within
 * `toleranceHours`, plus the next few alternatives to offer if nothing is close.
 */
function matchTourSlot(wantedIso, slots, toleranceHours) {
  var tolerance = (toleranceHours === undefined ? 4 : toleranceHours) * 3600000;
  var available = (slots || []).slice().sort();
  var result = { matched: null, delta_minutes: null, alternatives: available.slice(0, 3) };
  if (!wantedIso || !available.length) return result;

  var wanted = new Date(wantedIso).getTime();
  if (isNaN(wanted)) return result;

  var best = null;
  var bestDelta = Infinity;
  for (var i = 0; i < available.length; i++) {
    var delta = Math.abs(new Date(available[i]).getTime() - wanted);
    if (delta < bestDelta) { bestDelta = delta; best = available[i]; }
  }

  // Alternatives are the slots nearest what they asked for, not simply the
  // earliest ones - "how about Tuesday?" should not be answered with Monday 9am.
  result.alternatives = available
    .slice()
    .sort(function (a, b) {
      return Math.abs(new Date(a).getTime() - wanted) - Math.abs(new Date(b).getTime() - wanted);
    })
    .slice(0, 3)
    .sort();

  if (best !== null && bestDelta <= tolerance) {
    result.matched = best;
    result.delta_minutes = Math.round(bestDelta / 60000);
  }
  return result;
}

/**
 * Is this slot inside the manager's published tour policy, or an exception?
 *
 * Exceptions are held for a tap rather than refused. Returning reasons rather
 * than a bare boolean means the manager's card can say WHY it was held, which
 * is the difference between a useful notification and an interruption.
 *
 * `hourOverride` exists because a Code node cannot rely on the container's
 * timezone; the caller passes the local hour and weekday it computed.
 */
function classifyTourRequest(slotIso, policy, nowIso, hourOverride, weekdayOverride) {
  var reasons = [];
  var config = policy || {};
  var earliest = Number(config.earliest_hour === undefined ? 9 : config.earliest_hour);
  var latest = Number(config.latest_hour === undefined ? 18 : config.latest_hour);
  var minNotice = Number(config.min_notice_hours === undefined ? 12 : config.min_notice_hours);
  var allowWeekends = config.allow_weekends === undefined ? true : Boolean(config.allow_weekends);

  var slot = new Date(slotIso);
  var now = new Date(nowIso || new Date().toISOString());
  var hour = hourOverride === undefined || hourOverride === null ? slot.getUTCHours() : Number(hourOverride);
  var weekday = weekdayOverride === undefined || weekdayOverride === null
    ? slot.getUTCDay()
    : Number(weekdayOverride);

  if (hour < earliest || hour >= latest) {
    reasons.push("outside self-guided hours (" + earliest + ":00-" + latest + ":00)");
  }
  if (!allowWeekends && (weekday === 0 || weekday === 6)) {
    reasons.push("weekend");
  }
  var noticeHours = (slot.getTime() - now.getTime()) / 3600000;
  if (noticeHours < minNotice) {
    reasons.push("less than " + minNotice + "h notice (" + Math.max(0, Math.round(noticeHours)) + "h)");
  }

  return {
    is_exception: reasons.length > 0,
    reasons: reasons,
    notice_hours: Math.round(noticeHours),
  };
}

/* -------------------------------------------------------------- guardrails */

/**
 * Tier A guardrail. Runs on every message before it leaves, and again at send
 * time, because a manager may have edited the wording after it was drafted.
 *
 * Blocks: protected-class content, legal or lease commitments, rent negotiation,
 * availability promises, and invented numbers that are not in the unit facts.
 */
var PROTECTED_CLASS_PATTERNS = [
  { pattern: /\b(kids?|children|child|family friendly|families|school district)\b/i, label: "familial status" },
  { pattern: /\b(disab|wheelchair|handicap|mental health|service animal policy)\b/i, label: "disability" },
  { pattern: /\b(race|ethnic|nationality|immigration|citizen|visa status)\b/i, label: "national origin / race" },
  { pattern: /\b(church|mosque|temple|synagogue|religio)\b/i, label: "religion" },
  { pattern: /\b(marital status|married|single people|couples only)\b/i, label: "marital status" },
  { pattern: /\b(section 8|voucher|housing assistance|welfare)\b/i, label: "source of income" },
  { pattern: /\b(good neighborhood for|safe area for|type of people)\b/i, label: "steering" },
];

var COMMITMENT_PATTERNS = [
  { pattern: /\b(guarantee|guaranteed|we promise|you will be approved|pre-?approved)\b/i, label: "approval commitment" },
  { pattern: /\b(hold (it|the unit) for you|reserved for you|it'?s yours)\b/i, label: "availability commitment" },
  { pattern: /\b(we can lower|discount the rent|negotiate the rent|reduce the rent)\b/i, label: "rent negotiation" },
  { pattern: /\b(legally|by law|you are entitled|your rights under)\b/i, label: "legal statement" },
  { pattern: /\b(denied|rejected|you do not qualify|we cannot rent to you)\b/i, label: "adverse decision language" },
];

function guardrailCheck(text, knowledge) {
  var findings = [];
  var body = String(text || "");

  PROTECTED_CLASS_PATTERNS.forEach(function (rule) {
    if (rule.pattern.test(body)) {
      findings.push({ severity: "block", category: "protected_class", detail: rule.label });
    }
  });

  COMMITMENT_PATTERNS.forEach(function (rule) {
    if (rule.pattern.test(body)) {
      findings.push({ severity: "block", category: "commitment", detail: rule.label });
    }
  });

  // Any dollar figure in the message must appear in the unit facts. Catches the
  // model inventing a rent, fee, or deposit.
  if (knowledge) {
    var allowed = [];
    Object.keys(knowledge).forEach(function (key) {
      var value = knowledge[key];
      if (typeof value === "number") allowed.push(Math.round(value));
      if (typeof value === "string") {
        var found = value.match(/\d[\d,]*(\.\d+)?/g) || [];
        found.forEach(function (n) { allowed.push(Math.round(Number(n.replace(/,/g, "")))); });
      }
    });

    var quoted = body.match(/\$\s?\d[\d,]*(\.\d+)?/g) || [];
    quoted.forEach(function (raw) {
      var amount = Math.round(Number(raw.replace(/[$,\s]/g, "")));
      if (allowed.indexOf(amount) === -1) {
        findings.push({
          severity: "block",
          category: "unsupported_figure",
          detail: raw.trim() + " is not in the unit facts",
        });
      }
    });
  }

  var blocking = findings.filter(function (f) { return f.severity === "block"; });
  return {
    passed: blocking.length === 0,
    findings: findings,
    checked_at: new Date().toISOString(),
  };
}

/* ------------------------------------------------------- pre-qualification */

/**
 * Scheduling triage only. This is NOT a rental decision and its output must
 * never be phrased to a prospect as a denial.
 *
 * Deliberately narrow: move-in timing, self-reported income against the
 * published multiple, pet policy, and occupancy. Nothing else is considered and
 * nothing here is verified.
 */
function prequalGate(answers, unit, config) {
  var reasons = [];
  var missing = [];
  var incomeMultiple = config && config.income_multiple ? Number(config.income_multiple) : 3;

  if (!answers || answers.move_in_date === null || answers.move_in_date === undefined) {
    missing.push("move_in_date");
  } else {
    var availableFrom = new Date(unit.available_from);
    var wanted = new Date(answers.move_in_date);
    var daysAfter = (wanted - availableFrom) / 86400000;

    if (daysAfter < -14) {
      reasons.push({
        criterion: "move_in_timing",
        met: false,
        detail: "wants " + answers.move_in_date + ", unit is available from " + unit.available_from,
      });
    } else if (daysAfter > 60) {
      reasons.push({
        criterion: "move_in_timing",
        met: false,
        detail: "move-in is more than 60 days after the unit is available",
      });
    } else {
      reasons.push({ criterion: "move_in_timing", met: true, detail: answers.move_in_date });
    }
  }

  if (answers && (answers.stated_monthly_income === null || answers.stated_monthly_income === undefined)) {
    missing.push("stated_monthly_income");
  } else if (answers) {
    // Self-reported and unverified. Verification happens after an application.
    var rent = Number(unit.rent_amount);
    var stated = Number(answers.stated_monthly_income);
    var ratio = stated / rent;
    reasons.push({
      criterion: "stated_income",
      met: ratio >= incomeMultiple,
      detail: "$" + stated + "/mo stated against $" + rent + " rent = " + ratio.toFixed(2) + "x (unverified)",
    });
  }

  if (answers && answers.pets && String(answers.pets).toLowerCase() !== "none") {
    var weightMatch = String(answers.pets).match(/(\d+)\s?(lb|pound)/i);
    var overLimit = weightMatch && Number(weightMatch[1]) > 50;
    reasons.push({
      criterion: "pets",
      met: !overLimit,
      detail: overLimit ? "stated pet is over the 50 lb limit" : String(answers.pets),
    });
  }

  var failed = reasons.filter(function (r) { return r.met === false; });
  var result = missing.length ? "incomplete" : failed.length ? "not_clear" : "clear";

  return {
    result: result,
    reasons: reasons,
    missing: missing,
    evaluated_at: new Date().toISOString(),
  };
}

/* ------------------------------------------------------- AI output shape */

/**
 * Unwraps structured output from the OpenAI node.
 *
 * The payload arrives wrapped differently depending on node version, whether
 * simplify is on, and whether a JSON schema was applied - sometimes a parsed
 * object, sometimes a JSON string under `output`, sometimes nested one level
 * deeper. Probing for a known key is more robust than assuming a shape.
 *
 * @param {*} data       the item's json
 * @param {string} anchor a key that must exist on the real payload
 */
function unwrapAiPayload(data, anchor) {
  var value = data;

  for (var depth = 0; depth < 6; depth++) {
    if (value === null || value === undefined) break;

    if (typeof value === "string") {
      var trimmed = value.trim();
      if (trimmed.charAt(0) !== "{" && trimmed.charAt(0) !== "[") break;
      try {
        value = JSON.parse(trimmed);
      } catch (error) {
        break;
      }
      continue;
    }

    if (Array.isArray(value)) {
      value = value[0];
      continue;
    }

    if (typeof value === "object") {
      if (Object.prototype.hasOwnProperty.call(value, anchor)) return value;

      var next =
        value.output !== undefined ? value.output :
        value.message !== undefined ? value.message :
        value.content !== undefined ? value.content :
        value.text !== undefined ? value.text :
        value.json !== undefined ? value.json : undefined;

      if (next === undefined) break;
      value = next;
      continue;
    }

    break;
  }

  return value;
}

/* ------------------------------------------------------------- lock code */

/**
 * Self-guided tour entry code.
 *
 * MOCK. A real deployment issues this through a smart-lock platform
 * (Rently, Tour24, ButterflyMX) bound to the booking window. Here it is
 * generated locally and logged, and every record it touches is marked
 * source: "mock".
 */
function generateLockCode() {
  var code = String(Math.floor(Math.random() * 900000) + 100000);
  return { code: code, source: "mock", issued_at: new Date().toISOString() };
}

// Tier A guardrail, run on the COMPOSED text - the model's answer plus the
// fixed question or booking link the system appended. Whatever is about to
// leave is what gets checked, never an earlier draft.
const turn = $input.first().json;
const context = $('Build Conversation Context').first().json;

// The allowlist is unit facts PLUS what the prospect themselves stated.
// Confirming a figure someone just gave you is not an invented figure, and
// without this every 'got it, $5,000 a month' reply is blocked and the
// conversation stalls in silence on the most ordinary turn there is.
const knowledge = buildConversationKnowledge(context.unit, turn.answers);
const verdict = guardrailCheck(turn.reply_text, knowledge);

// The guardrail and the message_log see the real text. Only the copy that
// goes to Telegram is escaped, because that one is parsed for HTML entities.
return [{ json: Object.assign({}, turn, {
  guardrail_passed: verdict.passed,
  guardrail_result: verdict,
  reply_html: escapeTelegramHtml(turn.reply_text),
  findings_text: escapeTelegramHtml(JSON.stringify(verdict.findings)),
  reasons_text: escapeTelegramHtml(JSON.stringify(turn.prequal_reasons)),
}) }];

